use std::io;
use std::str;

pub struct Scanner<R> {
    reader: R,
    buffer: Vec<String>,
}

impl<R: io::BufRead> Scanner<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: vec![],
        }
    }

    pub fn token<T: str::FromStr>(&mut self) -> T {
        loop {
            if let Some(token) = self.buffer.pop() {
                return token.parse().ok().expect("Failed parse");
            }
            let mut input = String::new();
            self.reader.read_line(&mut input).expect("Failed read");
            self.buffer = input.split_whitespace().rev().map(String::from).collect();
        }
    }
}

fn factorize(n: i64) -> Vec<i64> {
    let mut n = n;
    let mut ans = Vec::new();
    let mut d = 2;
    while d * d <= n {
        while n % d == 0 {
            ans.push(d);
            n /= d;
        }
        d += 1;
    }
    if n > 1 {
        ans.push(n);
    }
    ans
}

fn solve<R: io::BufRead, W: io::Write>(scan: &mut Scanner<R>, out: &mut W) {
    let n: i64 = scan.token();
    let k: i64 = scan.token();

    let factors = factorize(n);
    let num_factors = factors.len() as i64;
    if num_factors < k {
        writeln!(out, "-1").ok();
        return;
    }
    // Choose (k - 1) factors individually.
    // Make the k-th factor the product of the rest of the factors.
    for i in 0..(k - 1) {
        write!(out, "{} ", factors[i as usize]).ok();
    }
    let mut last_factor = 1;
    for i in (k - 1)..num_factors {
        last_factor *= factors[i as usize];
    }
    writeln!(out, "{}", last_factor).ok();
}

fn main() {
    let (stdin, stdout) = (io::stdin(), io::stdout());
    let mut scan = Scanner::new(stdin.lock());
    let mut out = io::BufWriter::new(stdout.lock());
    solve(&mut scan, &mut out);
}

